const D=[
['georgia-borano','Borano (Ajarian Cheese in Browned Butter)',25,['sulguni cheese','butter','egg','water'],[[140,'g'],[35,'g'],[1,'piece'],[30,'ml']],['Melt the butter over medium-low heat until it smells nutty but is not burnt.','Add shredded cheese and measured water, then stir until the cheese softens.','Pour in the beaten egg and cook gently, stirring only enough to combine.','Remove from heat when creamy and serve immediately with bread.']],
['georgia-satsivi','Satsivi (Georgian Chicken in Walnut Sauce)',70,['chicken thigh','walnuts','onion','chicken stock','garlic','ground coriander','fenugreek','white wine vinegar'],[[220,'g'],[80,'g'],[60,'g'],[220,'ml'],[6,'g'],[0.5,'tsp'],[0.25,'tsp'],[1,'tsp']],['Poach the chicken in stock until safely cooked, then reserve the meat and broth.','Cook the onion gently, then blend it with walnuts, garlic, coriander and fenugreek.','Whisk the walnut paste into warm broth and simmer until thick and smooth.','Add the chicken, heat briefly, stir in vinegar off the heat and cool before serving.']],
['georgia-gebzhalia','Gebzhalia (Megrelian Mint Cheese Rolls)',30,['sulguni cheese','milk','mint','sour cream','adjika'],[[160,'g'],[220,'ml'],[8,'g'],[60,'g'],[0.5,'tsp']],['Warm the milk until steaming but not boiling.','Soften sliced cheese in the milk, lift it out and flatten it while pliable.','Spread with chopped mint and a little adjika, roll tightly and slice.','Whisk sour cream with enough warm milk to make a sauce and spoon it around the rolls.']],
['georgia-megrelian-kharcho','Megrelian Kharcho (Spicy Beef and Walnut Stew)',80,['beef chuck','walnuts','onion','beef stock','tomato paste','adjika','garlic','ground coriander'],[[190,'g'],[65,'g'],[70,'g'],[280,'ml'],[20,'g'],[1,'tsp'],[6,'g'],[0.5,'tsp']],['Brown the beef in a heavy pan, then add chopped onion and soften it.','Stir in tomato paste, adjika, garlic and coriander.','Add stock, cover and simmer until the beef is tender.','Blend the walnuts with a little hot broth, stir them in and simmer uncovered until rich and thick.']],
['georgia-abkhazura','Abkhazura (Georgian Spiced Meat Patties)',40,['ground beef','ground pork','caul fat','onion','garlic','pomegranate seeds','ground coriander','smoked paprika'],[[110,'g'],[90,'g'],[60,'g'],[45,'g'],[5,'g'],[35,'g'],[0.5,'tsp'],[0.5,'tsp']],['Mix both meats with finely chopped onion, garlic, coriander and smoked paprika.','Shape into small oval patties and wrap each one securely in caul fat.','Pan-fry over medium heat, turning, until browned and safely cooked through.','Rest briefly and serve hot with pomegranate seeds.']],
['georgia-chakapuli','Chakapuli (Georgian Lamb and Tarragon Stew)',75,['lamb shoulder','tarragon','green plums','dry white wine','spring onion','coriander leaves','garlic','water'],[[210,'g'],[25,'g'],[80,'g'],[120,'ml'],[45,'g'],[15,'g'],[6,'g'],[120,'ml']],['Layer lamb, chopped spring onion, garlic, coriander, tarragon and green plums in a pot.','Pour over the wine and measured water without browning the ingredients.','Cover and simmer gently until the lamb is tender.','Uncover for the final minutes, adjust the broth and serve fragrant and hot.']],
['georgia-shkmeruli','Shkmeruli (Rachan Garlic Chicken in Milk)',45,['chicken thigh','milk','butter','garlic','black pepper'],[[260,'g'],[160,'ml'],[20,'g'],[12,'g'],[0.25,'tsp']],['Season the chicken and press it skin-side down in a buttered heavy pan until crisp.','Turn and cook until the thickest part reaches a safe temperature, then cut into pieces.','Gently fry crushed garlic in the pan drippings without browning it.','Add milk, simmer for two minutes, return the chicken and heat until coated.']],
['georgia-mtiuletian-khinkali','Mtiuletian Khinkali (Georgian Mountain Meat Dumplings)',65,['wheat flour','water','ground beef','ground pork','onion','cumin','black pepper'],[[120,'g'],[95,'ml'],[85,'g'],[55,'g'],[40,'g'],[0.25,'tsp'],[0.25,'tsp']],['Knead flour with part of the water into a firm dough, rest it, then roll thin rounds.','Mix the meats, grated onion, cumin and pepper, gradually adding the remaining water for a juicy filling.','Place filling on each round, pleat the edges upward and twist the top closed.','Boil gently until the dumplings float, then cook several minutes more and serve hot.']],
['georgia-ajapsandali','Ajapsandali (Georgian Eggplant and Basil Stew)',45,['eggplant','tomato','red pepper','potato','onion','garlic','basil','sunflower oil'],[[180,'g'],[160,'g'],[90,'g'],[100,'g'],[60,'g'],[5,'g'],[10,'g'],[18,'ml']],['Salt the eggplant pieces for 15 minutes, then rinse, squeeze and pat dry.','Brown the eggplant in part of the oil and set it aside; soften onion and pepper in the pan.','Add tomato, par-cooked potato and garlic, then return the eggplant.','Cover and simmer until tender, fold in basil and rest briefly before serving.']],
['georgia-lobio','Lobio (Georgian Bean and Herb Stew)',50,['cooked kidney beans','onion','walnuts','garlic','coriander leaves','fenugreek','red wine vinegar','water'],[[260,'g'],[65,'g'],[35,'g'],[5,'g'],[12,'g'],[0.25,'tsp'],[2,'tsp'],[120,'ml']],['Soften chopped onion in a saucepan with a spoonful of water.','Add beans and measured water, then simmer until the beans are very tender.','Mash part of the beans and stir in ground walnuts, garlic and fenugreek.','Simmer until thick, then finish with coriander and vinegar off the heat.']]
].map(a=>({id:a[0],n:a[1],c:'Georgia',f:'🇬🇪',m:a[2],x:a[3],q:a[4],s:a[5],source:SRC,co:'#a71930',license:L,sourceNote:N}));
window.EXTRA_RECIPES=(window.EXTRA_RECIPES||[]).concat(D); window.RECIPE_I18N=window.RECIPE_I18N||{};
const T={
'georgia-borano':{ko:['보라노(아자리야식 버터 치즈 요리)',['버터를 중약불에서 견과 향이 날 때까지 녹이되 태우지 않습니다.','채 썬 치즈와 계량한 물을 넣고 치즈가 부드러워질 때까지 저어줍니다.','푼 달걀을 붓고 약불에서 부드럽게 익힙니다.','크림처럼 되면 바로 불에서 내려 빵과 함께 냅니다.']],es:['Borano (queso adjariano con mantequilla dorada)',['Derrite la mantequilla a fuego medio-bajo hasta que huela a nuez sin quemarla.','Añade el queso rallado y el agua medida; remueve hasta ablandarlo.','Vierte el huevo batido y cocina suavemente.','Retira cuando esté cremoso y sirve enseguida con pan.']],ja:['ボラノ（アジャリア風焦がしバターチーズ）',['バターを中弱火で焦がさず香ばしく溶かします。','細切りチーズと計量した水を加え、柔らかくなるまで混ぜます。','溶き卵を注ぎ、弱火でやさしく火を通します。','クリーム状になったら火を止め、パンとすぐに供します。']],zh:['博拉诺（阿扎尔黄油奶酪）',['用中小火融化黄油至有坚果香气，注意不要烧焦。','加入奶酪丝和定量清水，搅拌至奶酪变软。','倒入蛋液，用小火轻柔加热。','呈奶油状时离火，立即配面包食用。']]},
'georgia-satsivi':{ko:['사치비(조지아식 호두소스 닭고기)',['닭고기를 육수에 안전하게 익히고 고기와 육수를 따로 둡니다.','양파를 부드럽게 볶아 호두·마늘·고수씨·호로파와 곱게 갑니다.','호두 페이스트를 따뜻한 육수에 풀어 걸쭉하게 끓입니다.','닭고기를 넣어 데운 뒤 불을 끄고 식초를 섞어 식혀 냅니다.']],es:['Satsivi (pollo georgiano en salsa de nuez)',['Escalfa el pollo en el caldo hasta que esté bien cocido y reserva ambos.','Ablanda la cebolla y tritúrala con nueces, ajo, cilantro y fenogreco.','Bate la pasta de nuez con caldo caliente y cuece hasta espesar.','Añade el pollo, calienta, incorpora el vinagre fuera del fuego y deja enfriar.']],ja:['サツィヴィ（ジョージア風鶏肉のくるみソース）',['鶏肉をだしで安全に火が通るまでゆで、肉とだしを分けます。','玉ねぎを柔らかくし、くるみ、にんにく、コリアンダー、フェヌグリークと攪拌します。','くるみペーストを温かいだしに溶き、濃くなるまで煮ます。','鶏肉を加えて温め、火を止めて酢を混ぜ、冷まして供します。']],zh:['萨齐维（格鲁吉亚核桃酱鸡肉）',['将鸡肉在高汤中煮熟，分别保留鸡肉和汤。','炒软洋葱，与核桃、大蒜、芫荽籽和胡芦巴打匀。','把核桃糊调入温热高汤，煮至浓稠顺滑。','加入鸡肉略热，离火拌入醋，冷却后食用。']]},
'georgia-gebzhalia':{ko:['게브잘리아(메그렐리식 민트 치즈롤)',['우유를 끓기 직전까지 데웁니다.','치즈를 우유에서 부드럽게 한 뒤 꺼내 얇게 폅니다.','민트와 아지카를 펴 바르고 단단히 말아 썹니다.','사워크림에 따뜻한 우유를 섞어 소스를 만들고 치즈롤에 곁들입니다.']],es:['Gebzhalia (rollos megrelianos de queso y menta)',['Calienta la leche sin dejar que hierva.','Ablanda el queso en la leche, retíralo y aplánalo mientras esté flexible.','Unta menta y adjika, enrolla bien y corta.','Mezcla crema agria con leche tibia y sirve la salsa alrededor.']],ja:['ゲブジャリア（メグレル風ミントチーズロール）',['牛乳を沸騰直前まで温めます。','チーズを牛乳で柔らかくし、取り出して薄く伸ばします。','ミントとアジカを塗り、固く巻いて切ります。','サワークリームを温かい牛乳でのばし、周りに注ぎます。']],zh:['格布扎利亚（明格列尔薄荷奶酪卷）',['将牛奶加热至冒蒸汽但不沸腾。','把奶酪在牛奶中泡软，取出趁软压平。','抹上薄荷和阿吉卡，卷紧后切段。','酸奶油加温牛奶调成酱，淋在奶酪卷周围。']]},
'georgia-megrelian-kharcho':{ko:['메그렐리 하르초(매콤한 소고기 호두 스튜)',['소고기를 갈색으로 굽고 다진 양파를 넣어 부드럽게 익힙니다.','토마토 페이스트·아지카·마늘·고수씨를 섞습니다.','육수를 붓고 덮어 고기가 부드러워질 때까지 끓입니다.','호두를 뜨거운 육수와 갈아 넣고 뚜껑 없이 걸쭉하게 끓입니다.']],es:['Kharcho megreliano (estofado picante de ternera y nuez)',['Dora la ternera y ablanda la cebolla picada.','Incorpora tomate concentrado, adjika, ajo y cilantro.','Añade caldo, tapa y cocina hasta ablandar la carne.','Tritura las nueces con caldo, incorpóralas y reduce sin tapa.']],ja:['メグレル風ハルチョー（辛い牛肉とくるみの煮込み）',['牛肉を焼き、刻み玉ねぎを加えて柔らかくします。','トマトペースト、アジカ、にんにく、コリアンダーを混ぜます。','だしを加え、蓋をして肉が柔らかくなるまで煮ます。','くるみを熱いだしと攪拌して加え、蓋なしで濃く煮詰めます。']],zh:['明格列尔哈尔乔（辣味牛肉核桃炖菜）',['将牛肉煎上色，加入洋葱碎炒软。','拌入番茄膏、阿吉卡、大蒜和芫荽籽。','倒入高汤，加盖炖至牛肉软嫩。','核桃加热汤打碎后倒入，不加盖煮至浓稠。']]},
'georgia-abkhazura':{ko:['압하주라(조지아식 향신료 고기완자)',['두 고기에 양파·마늘·고수씨·훈제 파프리카를 섞습니다.','작은 타원형으로 빚어 창자지방막으로 단단히 감쌉니다.','중불에서 돌려가며 갈색이 나고 속까지 안전하게 익도록 굽습니다.','잠시 쉬게 한 뒤 석류알과 뜨겁게 냅니다.']],es:['Abkhazura (albóndigas georgianas especiadas)',['Mezcla ambas carnes con cebolla, ajo, cilantro y pimentón ahumado.','Forma óvalos pequeños y envuélvelos bien en redaño.','Fríe a fuego medio, girando, hasta dorar y cocinar por completo.','Deja reposar y sirve caliente con granada.']],ja:['アブハズラ（ジョージア風スパイス肉団子）',['2種類の肉に玉ねぎ、にんにく、コリアンダー、燻製パプリカを混ぜます。','小判形にし、網脂でしっかり包みます。','中火で返しながら焼き、中心まで安全に火を通します。','少し休ませ、ざくろの実を添えて熱々で供します。']],zh:['阿布哈祖拉（格鲁吉亚香料肉饼）',['两种肉与洋葱、大蒜、芫荽籽和烟熏红椒粉拌匀。','做成小椭圆饼，用网油包严。','中火翻面煎至上色并确保中心熟透。','稍作静置，配石榴籽趁热食用。']]},
'georgia-chakapuli':{ko:['차카풀리(조지아식 양고기 타라곤 스튜)',['냄비에 양고기·파·마늘·고수잎·타라곤·청매실을 층층이 담습니다.','볶지 않고 와인과 계량한 물을 붓습니다.','덮어 양고기가 부드러워질 때까지 약불로 끓입니다.','마지막에 뚜껑을 열어 국물을 맞추고 향긋할 때 뜨겁게 냅니다.']],es:['Chakapuli (estofado georgiano de cordero y estragón)',['Coloca en capas cordero, cebolleta, ajo, cilantro, estragón y ciruelas verdes.','Vierte vino y agua medida sin dorar los ingredientes.','Tapa y cocina suavemente hasta que el cordero esté tierno.','Destapa al final, ajusta el caldo y sirve aromático y caliente.']],ja:['チャカプリ（ジョージア風ラムとタラゴンの煮込み）',['鍋にラム、青ねぎ、にんにく、香菜、タラゴン、青梅を重ねます。','材料を炒めず、ワインと計量した水を注ぎます。','蓋をしてラムが柔らかくなるまで弱火で煮ます。','最後に蓋を外して汁を調整し、香り高いうちに供します。']],zh:['恰卡普里（格鲁吉亚羊肉龙蒿炖菜）',['将羊肉、葱、大蒜、香菜、龙蒿和青李子分层放入锅中。','不煎炒，倒入葡萄酒和定量清水。','加盖小火炖至羊肉软嫩。','最后揭盖调整汤量，趁香气浓郁时热食。']]},
'georgia-shkmeruli':{ko:['슈크메룰리(라차식 마늘 우유 닭고기)',['닭고기에 간하고 버터 두른 무거운 팬에서 껍질을 눌러 바삭하게 굽습니다.','뒤집어 가장 두꺼운 부분까지 안전하게 익힌 뒤 조각냅니다.','팬의 기름에 으깬 마늘을 갈색이 나지 않게 볶습니다.','우유를 넣어 2분 끓이고 닭고기를 돌려 넣어 소스를 입힙니다.']],es:['Shkmeruli (pollo rachano con ajo y leche)',['Sazona el pollo y presiónalo con la piel abajo en una sartén con mantequilla.','Dale la vuelta, cocina el centro de forma segura y córtalo.','Fríe suavemente el ajo machacado en la grasa sin dorarlo.','Añade leche, hierve dos minutos y devuelve el pollo para cubrirlo.']],ja:['シュクメルリ（ラチャ風にんにくミルクチキン）',['鶏肉を調味し、バターを入れた厚手の鍋で皮を押さえて香ばしく焼きます。','裏返して中心まで安全に火を通し、切り分けます。','残った脂で潰したにんにくを焦がさず炒めます。','牛乳を加えて2分煮て、鶏肉を戻しソースを絡めます。']],zh:['什克梅鲁利（拉恰蒜香牛奶鸡）',['鸡肉调味后，皮朝下压在加黄油的厚锅中煎脆。','翻面确保最厚处熟透，再切成块。','用锅中油脂轻炒压碎的大蒜，勿使其焦黄。','加入牛奶煮两分钟，放回鸡肉裹匀酱汁。']]},
'georgia-mtiuletian-khinkali':{ko:['므티울레티 힝칼리(조지아 산악식 고기만두)',['밀가루와 일부 물로 단단한 반죽을 치대 쉬게 하고 얇은 원형으로 밉니다.','두 고기·간 양파·커민·후추에 남은 물을 조금씩 섞어 촉촉한 소를 만듭니다.','반죽에 소를 얹고 가장자리를 위로 주름잡아 꼭지를 비틉니다.','약하게 끓는 물에서 떠오른 뒤 몇 분 더 익혀 뜨겁게 냅니다.']],es:['Khinkali mtiuletiano (dumplings georgianos de montaña)',['Amasa harina con parte del agua, reposa y estira discos finos.','Mezcla carnes, cebolla rallada, comino y pimienta; añade el agua restante.','Pon relleno en cada disco, pliega hacia arriba y gira el extremo.','Hierve suavemente; cuando floten, cocina unos minutos más y sirve.']],ja:['ムティウレティ風ヒンカリ（ジョージア山岳肉餃子）',['小麦粉と水の一部で固めの生地をこね、休ませて薄い円形に伸ばします。','2種類の肉、すりおろし玉ねぎ、クミン、胡椒に残りの水を混ぜます。','皮に餡を置き、縁を上にひだ寄せして先端をねじります。','静かにゆで、浮いてからさらに数分加熱して熱々で供します。']],zh:['姆季乌列季辛卡利（格鲁吉亚山地肉汤包）',['面粉加部分清水揉成较硬面团，醒面后擀成薄圆皮。','两种肉与洋葱泥、孜然、胡椒拌匀，逐步加入余水。','每张皮放馅，向上捏褶并扭紧顶部。','小火煮至浮起后再煮数分钟，趁热食用。']]},
'georgia-ajapsandali':{ko:['아잡산달리(조지아식 가지 바질 스튜)',['가지에 소금을 뿌려 15분 두고 헹군 뒤 물기를 꼭 짭니다.','기름 일부로 가지를 갈색 내어 덜고 양파와 파프리카를 부드럽게 익힙니다.','토마토·반쯤 익힌 감자·마늘을 넣고 가지를 다시 넣습니다.','덮어 부드럽게 익힌 뒤 바질을 섞고 잠시 두었다 냅니다.']],es:['Ajapsandali (estofado georgiano de berenjena y albahaca)',['Sala la berenjena 15 minutos, enjuaga, exprime y seca.','Dórala con parte del aceite; retírala y ablanda cebolla y pimiento.','Añade tomate, patata semicocida y ajo; devuelve la berenjena.','Tapa, cuece hasta ablandar, incorpora albahaca y deja reposar.']],ja:['アジャプサンダリ（ジョージア風なすとバジルの煮込み）',['なすに塩をして15分置き、洗って水気を絞ります。','油の一部で焼いて取り出し、玉ねぎとパプリカを柔らかくします。','トマト、下ゆでしたじゃがいも、にんにくを加え、なすを戻します。','蓋をして柔らかく煮て、バジルを混ぜ少し休ませます。']],zh:['阿扎普桑达利（格鲁吉亚茄子罗勒炖菜）',['茄子撒盐静置15分钟，冲洗、挤水并擦干。','用部分油煎上色后取出，再炒软洋葱和甜椒。','加入番茄、半熟土豆和大蒜，放回茄子。','加盖炖软，拌入罗勒并稍作静置。']]},
'georgia-lobio':{ko:['로비오(조지아식 콩 허브 스튜)',['냄비에서 다진 양파를 물 한 숟가락과 부드럽게 익힙니다.','콩과 계량한 물을 넣고 콩이 매우 부드러워질 때까지 끓입니다.','콩 일부를 으깨고 간 호두·마늘·호로파를 섞습니다.','걸쭉하게 끓인 뒤 불을 끄고 고수잎과 식초를 섞습니다.']],es:['Lobio (estofado georgiano de judías y hierbas)',['Ablanda la cebolla picada con una cucharada de agua.','Añade judías y agua medida; cuece hasta que estén muy tiernas.','Machaca una parte e incorpora nueces, ajo y fenogreco.','Espesa a fuego lento y termina fuera del fuego con cilantro y vinagre.']],ja:['ロビオ（ジョージア風豆と香草の煮込み）',['刻み玉ねぎを少量の水で柔らかくします。','豆と計量した水を加え、豆がとても柔らかくなるまで煮ます。','豆の一部を潰し、くるみ、にんにく、フェヌグリークを混ぜます。','濃く煮て、火を止めて香菜と酢を加えます。']],zh:['洛比奥（格鲁吉亚豆子香草炖菜）',['洋葱碎加一勺水在锅中炒软。','加入豆子和定量清水，煮至豆子非常软。','压碎部分豆子，拌入核桃、大蒜和胡芦巴。','小火煮稠，离火后加入香菜和醋。']]}}
